import { createInterface } from 'node:readline';
const rl = createInterface({ input: process.stdin });
let n = 0;
for await (const line of rl) {
  if (!line.trim()) continue;
  let e;
  try { e = JSON.parse(line); } catch { continue; }
  const m = e.message ?? e;
  const role = m.role ?? e.type;
  if (role !== 'user') continue;
  let c = m.content;
  if (Array.isArray(c)) {
    c = c.filter((b) => b.type === 'text').map((b) => b.text).join('\n');
  }
  if (typeof c !== 'string' || !c.trim()) continue;
  if (c.includes('tool_use_id') ) continue;
  if (/^<(system-reminder|command-name|local-command)/.test(c.trim())) continue;
  n++;
  console.log('--- [' + (e.timestamp ?? '') + ']');
  console.log(c.slice(0, 1400));
}
console.error('user msgs: ' + n);

import { createInterface } from 'node:readline';
const rl = createInterface({ input: process.stdin });
const rows = [];
for await (const line of rl) {
  if (!line.trim()) continue;
  let e;
  try { e = JSON.parse(line); } catch { continue; }
  const m = e.message ?? e;
  const role = m.role ?? e.type;
  let desc = '';
  const c = m.content;
  if (Array.isArray(c)) {
    for (const b of c) {
      if (b.type === 'text') desc += '[text] ' + b.text.slice(0, 300) + '\n';
      else if (b.type === 'tool_use') desc += '[tool_use ' + b.name + '] ' + JSON.stringify(b.input).slice(0, 300) + '\n';
      else if (b.type === 'tool_result') desc += '[tool_result] ' + JSON.stringify(b.content).slice(0, 200) + '\n';
    }
  } else if (typeof c === 'string') desc = '[str] ' + c.slice(0, 300);
  rows.push({ ts: e.timestamp, role, desc });
}
const idx = [];
rows.forEach((r, i) => { if (r.desc.includes('Request interrupted')) idx.push(i); });
for (const i of idx) {
  console.log('======== interruption at ' + i);
  for (let j = Math.max(0, i - 6); j <= Math.min(rows.length - 1, i + 2); j++) {
    console.log('--- ' + rows[j].ts + ' ' + rows[j].role);
    console.log(rows[j].desc);
  }
}
console.error('rows ' + rows.length);

